//refAssemblies: TCAdmin.Monitor.SDK.dll, System.Xml.ReaderWriter.dll, System.Private.Xml.Linq.dll, System.Xml.XDocument.dll, System.Diagnostics.Process.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Xml.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

var root = (string)ThisService.RootDirectory;

// The mods folder and a config_player.xml that lists the enabled content packages (the Workshop scripts add to it).
// Created here, before any mod is installed, so that a mod install never owns (and an uninstall never deletes) them.
var localMods = Path.Combine(root, "LocalMods");
if (!Directory.Exists(localMods))
{
    Directory.CreateDirectory(localMods);
    GiveToServiceUser(localMods, true);
}
var playerConfig = Path.Combine(root, "config_player.xml");
if (!File.Exists(playerConfig))
{
    File.WriteAllText(playerConfig, "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<config language=\"English\" savepath=\"Saves\">\n  <contentpackages>\n    <corepackage path=\"Content/ContentPackages/Vanilla.xml\" />\n    <regularpackages />\n  </contentpackages>\n</config>\n");
    GiveToServiceUser(playerConfig, false);
    ScriptConsole.WriteLine((object)"Created config_player.xml (vanilla content, no mods).");
}
else
{
    // Campaign saves go to the service's Saves folder, not the account's shared AppData (every service of the same
    // account would share one save folder, and backups would miss it). Only an empty save path is filled in.
    var config = XDocument.Load(playerConfig);
    var savePath = config.Root.Attributes().FirstOrDefault(a => string.Equals(a.Name.LocalName, "savepath", StringComparison.OrdinalIgnoreCase));
    if (savePath == null || string.IsNullOrWhiteSpace(savePath.Value))
    {
        if (savePath != null) savePath.Remove();
        config.Root.SetAttributeValue("savepath", "Saves");
        config.Save(playerConfig);
        ScriptConsole.WriteLine((object)"Campaign saves are kept in the Saves folder.");
    }
}

// Windows: the panel creates serversettings.xml from its template with an ACL of its own (no write access for the
// service account), and the server crashes on start when it saves its settings ("Access to the path ... is denied").
// Reset the file to the service folder's inherited permissions.
if (System.OperatingSystem.IsWindows())
{
    foreach (var name in new[] { "serversettings.xml", "config_player.xml" })
    {
        var file = Path.Combine(root, name);
        if (!File.Exists(file)) continue;
        using (var icacls = Process.Start(new ProcessStartInfo("icacls.exe", new[] { file, "/reset", "/Q" }) { UseShellExecute = false, RedirectStandardOutput = true, RedirectStandardError = true }))
        {
            var output = icacls.StandardOutput.ReadToEnd() + icacls.StandardError.ReadToEnd();
            icacls.WaitForExit();
            if (icacls.ExitCode != 0) ScriptConsole.WriteLine((object)("Could not reset the permissions of " + name + ": " + output.Trim()));
        }
    }
}

if (System.OperatingSystem.IsLinux())
{
    // Steam downloads lose the execute bit now and then.
    var server = Path.Combine(root, "DedicatedServer");
    if (File.Exists(server)) File.SetUnixFileMode(server, File.GetUnixFileMode(server) | UnixFileMode.UserExecute | UnixFileMode.GroupExecute);

    // The Steam game server (the query port, the server list) loads ~/.steam/sdk64/steamclient.so; the service root is
    // the home directory. Without it the server runs LAN/IP-only and never answers the query.
    var source = Path.Combine(root, "linux64", "steamclient.so");
    var sdk = Path.Combine(root, ".steam", "sdk64");
    var target = Path.Combine(sdk, "steamclient.so");
    if (File.Exists(source) && (!File.Exists(target) || new FileInfo(target).Length != new FileInfo(source).Length))
    {
        Directory.CreateDirectory(sdk);
        File.Copy(source, target, true);
        GiveToServiceUser(Path.Combine(root, ".steam"), true);
        ScriptConsole.WriteLine((object)"Copied steamclient.so to .steam/sdk64.");
    }

    // The console runs in GNU screen: the server only accepts commands on a terminal, and it asks that terminal for the
    // cursor position after every console message. screen answers; without a terminal that answers, the server stalls
    // until the next key press (and eats the stop command).
    if (!Shell("command -v screen", out _))
    {
        ScriptConsole.WriteLine((object)"GNU screen is missing on this host; installing it.");
        var installed =
            Shell("command -v apt-get && (DEBIAN_FRONTEND=noninteractive apt-get install -y screen || (apt-get update && DEBIAN_FRONTEND=noninteractive apt-get install -y screen))", out var aptLog)
            || Shell("command -v dnf && dnf install -y screen", out _)
            || Shell("command -v yum && yum install -y screen", out _);
        if (!installed) throw new Exception("GNU screen is missing and could not be installed. Install the screen package on this host. " + aptLog);
        ScriptConsole.WriteLine((object)"Installed GNU screen.");
    }
}

// The script runs as the monitor: hand what it creates to the service account (root-owned files are hidden in the file
// manager, and the server cannot write them).
void GiveToServiceUser(string path, bool directory)
{
    if (!System.OperatingSystem.IsLinux()) return;
    var credential = ServiceManagerService.GetServiceCredential(ThisService.ServiceId);
    if (directory) Globals.OperatingSystem.SetDirectoryOwner(path, credential.Domain, credential.UserName, true);
    else Globals.OperatingSystem.SetFileOwnerAutoDetect(path);
}

// Linux: install the shared libraries the server binary links but this host does not have.
if (System.OperatingSystem.IsLinux())
{
    var binary = Path.Combine(root, "DedicatedServer");
    var packages = new Dictionary<string, (string[] Apt, string[] Rpm)>
    {
        ["libstdc++.so.6"] = (new[] { "libstdc++6" }, new[] { "libstdc++" }),
        ["libgcc_s.so.1"] = (new[] { "libgcc-s1", "libgcc1" }, new[] { "libgcc" }),
        ["libz.so.1"] = (new[] { "zlib1g" }, new[] { "zlib" })
    };
    Shell("ldd '" + binary + "'", out var lddOutput);
    var missing = lddOutput.Split('\n').Where(l => l.Contains("=> not found")).Select(l => l.Trim().Split(' ')[0]).ToList();
    foreach (var soname in missing)
    {
        if (!packages.TryGetValue(soname, out var candidates))
        {
            ScriptConsole.WriteLine((object)("The server needs " + soname + ", which is not installed on this host."));
            continue;
        }
        ScriptConsole.WriteLine((object)(soname + " is missing on this host; installing it."));
        var apt = Shell("command -v apt-get", out _);
        var tool = apt ? "DEBIAN_FRONTEND=noninteractive apt-get install -y " : Shell("command -v dnf", out _) ? "dnf install -y " : "yum install -y ";
        var names = apt ? candidates.Apt : candidates.Rpm;
        var installed = names.Any(p => Shell(tool + p, out _));
        if (!installed && apt && Shell("apt-get update", out _)) installed = names.Any(p => Shell(tool + p, out _));
        if (!installed) throw new Exception(soname + " is missing and could not be installed. Install one of these packages on the host: " + string.Join(", ", names));
        ScriptConsole.WriteLine((object)("Installed " + soname + "."));
    }
}

bool Shell(string command, out string output)
{
    using (var process = Process.Start(new ProcessStartInfo("/bin/sh", new[] { "-c", command }) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false }))
    {
        output = process.StandardOutput.ReadToEnd() + process.StandardError.ReadToEnd();
        process.WaitForExit();
        return process.ExitCode == 0;
    }
}

//refAssemblies: TCAdmin.Monitor.SDK.dll, System.Xml.ReaderWriter.dll, System.Private.Xml.Linq.dll, System.Xml.XDocument.dll
using System;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Xml.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Barotrauma loads content packages from LocalMods/<folder>/filelist.xml when config_player.xml enables them.
// The Workshop download lands in steamapps/workshop/content/602960/<id>; move it to LocalMods/<id> and enable it
// in config_player.xml (a regular package, or the core package for a total conversion). The server loads it the
// next time it starts; players who join download it from the Workshop or from the server.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]+$")) throw new Exception("Unexpected Workshop id: " + fileId);
string installPath = Convert.ToString(Dynamic.InstallPath);
string root = (string)ThisService.RootDirectory;

if (!Directory.Exists(installPath))
{
    ScriptConsole.WriteLine((object)("Nothing was downloaded for Workshop item " + fileId + "."));
    return;
}

// The content package is the folder that holds filelist.xml (the item root for every current mod).
var fileList = Directory.GetFiles(installPath, "filelist.xml", SearchOption.AllDirectories)
    .OrderBy(p => p.Length).FirstOrDefault();
if (fileList == null)
{
    ScriptConsole.WriteLine((object)("Workshop item " + fileId + " has no filelist.xml; it is not a Barotrauma content package."));
    return;
}

string localMods = Path.Combine(root, "LocalMods");
bool createdLocalMods = !Directory.Exists(localMods);
Directory.CreateDirectory(localMods);
string target = Path.Combine(localMods, fileId);
if (Directory.Exists(target)) Directory.Delete(target, true);
Directory.Move(Path.GetDirectoryName(fileList), target);
try { if (Directory.Exists(installPath)) Directory.Delete(installPath, true); } catch { }

var package = XDocument.Load(Path.Combine(target, "filelist.xml")).Root;
string name = (string)package.Attribute("name") ?? fileId;
bool core = string.Equals((string)package.Attribute("corepackage"), "true", StringComparison.OrdinalIgnoreCase);
string packagePath = "LocalMods/" + fileId + "/filelist.xml";
ScriptConsole.WriteLine((object)("Installed \"" + name + "\" in LocalMods/" + fileId + "."));

// Enable it in config_player.xml (the server writes a full one on its first start; create a minimal one before that).
string configPath = Path.Combine(root, "config_player.xml");
bool configExisted = File.Exists(configPath);
var config = configExisted ? XDocument.Load(configPath) : new XDocument(new XElement("config"));
var packages = Child(config.Root, "contentpackages");
if (core)
{
    var corePackage = Child(packages, "corepackage");
    corePackage.RemoveAttributes();
    corePackage.SetAttributeValue("path", packagePath);
    ScriptConsole.WriteLine((object)("\"" + name + "\" is a core package (total conversion); it replaces the vanilla content."));
}
else
{
    if (Child(packages, "corepackage").Attribute("path") == null && Child(packages, "corepackage").Attribute("name") == null)
        Child(packages, "corepackage").SetAttributeValue("path", "Content/ContentPackages/Vanilla.xml");
    var regular = Child(packages, "regularpackages");
    if (!regular.Elements().Any(e => string.Equals(((string)e.Attribute("path") ?? "").Replace('\\', '/'), packagePath, StringComparison.OrdinalIgnoreCase)))
        regular.Add(new XElement("package", new XAttribute("path", packagePath)));
}
config.Save(configPath);
ScriptConsole.WriteLine((object)("Enabled \"" + name + "\" in config_player.xml. The server loads it the next time it starts."));

// The script runs as the monitor: give the new files to the service account (root-owned files are hidden in the
// file manager and the server cannot update them).
if (System.OperatingSystem.IsLinux())
{
    var credential = ServiceManagerService.GetServiceCredential(ThisService.ServiceId);
    Globals.OperatingSystem.SetDirectoryOwner(createdLocalMods ? localMods : target, credential.Domain, credential.UserName, true);
    if (!configExisted) Globals.OperatingSystem.SetFileOwnerAutoDetect(configPath);
}

// The element with this name (any case), created when missing.
XElement Child(XElement parent, string elementName)
{
    var element = parent.Elements().FirstOrDefault(e => string.Equals(e.Name.LocalName, elementName, StringComparison.OrdinalIgnoreCase));
    if (element == null) { element = new XElement(elementName); parent.Add(element); }
    return element;
}

