using System;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Xml.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Disables the Workshop content package in config_player.xml and removes LocalMods/<id>, which the install script
// created. A core package (total conversion) is replaced by the vanilla content again.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]+$")) throw new Exception("Unexpected Workshop id: " + fileId);
string root = (string)ThisService.RootDirectory;
string packagePath = "LocalMods/" + fileId + "/filelist.xml";

string configPath = Path.Combine(root, "config_player.xml");
if (File.Exists(configPath))
{
    var config = XDocument.Load(configPath);
    var packages = config.Root.Elements().FirstOrDefault(e => string.Equals(e.Name.LocalName, "contentpackages", StringComparison.OrdinalIgnoreCase));
    bool changed = false;
    if (packages != null)
    {
        foreach (var element in packages.Descendants().ToList())
        {
            if (!string.Equals(((string)element.Attribute("path") ?? "").Replace('\\', '/'), packagePath, StringComparison.OrdinalIgnoreCase)) continue;
            if (string.Equals(element.Name.LocalName, "corepackage", StringComparison.OrdinalIgnoreCase))
            {
                element.RemoveAttributes();
                element.SetAttributeValue("path", "Content/ContentPackages/Vanilla.xml");
            }
            else element.Remove();
            changed = true;
        }
    }
    if (changed)
    {
        config.Save(configPath);
        ScriptConsole.WriteLine((object)("Disabled LocalMods/" + fileId + " in config_player.xml."));
    }
}

string target = Path.Combine(root, "LocalMods", fileId);
if (Directory.Exists(target))
{
    try
    {
        Directory.Delete(target, true);
        ScriptConsole.WriteLine((object)("Removed LocalMods/" + fileId + "."));
    }
    catch (Exception ex)
    {
        ScriptConsole.WriteLine((object)("Could not remove LocalMods/" + fileId + " (" + ex.Message + "). Stop the server and uninstall again."));
        throw;
    }
}
